/**
 * @summary Training impact stats — overrides and corrections applied counts
 */
export const getGetOverrideImpactUrl = (params?: GetOverrideImpactParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/training/override-impact?${stringifiedParams}`
    : `/api/training/override-impact`;
};

